<img alt="CODIHA Club Logo" class:animated width="100%" src="/logo.png" />

<style>
  img {
    transition: fill var(--transition-duration) var(--transition-easing);
  }

  :global(html.dark) img {
    filter: brightness(0) invert(1);
  }

  img.animated {
    animation: logo-animation 3s ease-in-out infinite;
  }

  @keyframes logo-animation {
    /* animate paths [0, 1, 2] opacity with slight delay between them */
    0% {
      transform: rotate(0);
    }
    100% {
      transform: rotate(360deg);
    }
  }
</style>
